mapper.select:
SELECT a.*, p.real_name AS patient_name, d.real_name AS doctor_name, dp.name AS department_name FROM appointment a JOIN patient p ON p.id = a.patient_id JOIN doctor d ON d.id = a.doctor_id JOIN department dp ON dp.id = a.department_id
WHERE a.status = #{status}
ORDER BY a.appointment_date DESC, a.id DESC LIMIT #{size} OFFSET #{offset}

